\Eq{f(x):=(\cM\inv\phi)(x)=\frac{1}{2\pi}\int_{c-i\oo}^{c+i\oo}x^{-s}\phi(s)ds,}
where $c\in\R$ is any values in between $a$ and $b$.
\end{Thm}

